<script>
function hexdump(arr){
    function pad(num, size) {
        num = num.toString();
        while (num.length < size) num = "0" + num;
        return num;
    }
    let s = ""
    for(v of arr){
        if(v<0){
            v = v+256;
        }
        s += "0x"+pad(v.toString(16),2)+","
    }    
    return s
}

function inputFromDouble(){
